function parseRavenLimit(value, fallback = 6) {
  const parsed = Number(value);
  return parsed || fallback;
}

module.exports = { parseRavenLimit };

const assert = require('node:assert/strict');
const { parseRavenLimit } = require('../src/ravenHarness.js');

assert.equal(parseRavenLimit(' 12 '), 12);
assert.equal(parseRavenLimit('0'), 0);
assert.equal(parseRavenLimit('bad', 9), 9);

#!/usr/bin/env bash
set -euo pipefail
node test/ravenHarness.test.js

